220	fn find_session(id: &str) -> Option<PathBuf> {
221	    let p = PathBuf::from(id);
222	    if p.exists() { return Some(p); }
223	    if let Ok(home) = std::env::var("HOME") {
224	        let projects = PathBuf::from(&home).join(".claude/projects");
225	        if let Ok(entries) = std::fs::read_dir(&projects) {
226	            for entry in entries.flatten() {
227	                let candidate = entry.path().join(format!("{id}.jsonl"));
228	                if candidate.exists() { return Some(candidate); }
229	            }
230	        }
231	    }
232	    // Fall back to extracting the latest checkpoint's full.jsonl from the
233	    // entire/checkpoints/v1 branch. Used when this session was authored on
234	    // another machine and never produced a local Claude Code log.
235	    extract_from_checkpoint(id)
236	}
