487	// ── Text extraction (for clipboard) ──────────────────────────────────────────
488	
489	fn card_text(card: &Card) -> String {
490	    let mut out = String::new();
491	    match card {
492	        Card::RepoLink { name, dir, branch } => {
493	            out.push_str(name); out.push('\n');
494	            out.push_str(dir);  out.push('\n');
495	            if !branch.is_empty() { out.push_str(branch); out.push('\n'); }
496	        }
497	        Card::Header { title, cwd, branch, agent, .. } => {
498	            if let Some(t) = title { out.push_str(t); out.push('\n'); }
499	            if !cwd.is_empty()    { out.push_str(cwd);               out.push('\n'); }
500	            if !branch.is_empty() { out.push_str(&format!("[{branch}]")); out.push('\n'); }
501	            if !agent.is_empty()  { out.push_str(agent); out.push('\n'); }
502	        }
503	        Card::System { content, .. } => { if !content.is_empty() { out.push_str(content); out.push('\n'); } }
504	        Card::UserMsg { parts, .. } => {
505	            for part in parts {
506	                match part {
507	                    UserPart::Text(t) => { out.push_str(t); out.push('\n'); }
508	                    UserPart::ToolResult { name, content, .. } => {
509	                        out.push_str(&format!("[Result: {name}]\n{content}\n"));
510	                    }
511	                }
512	            }
513	        }
514	        Card::AsstMsg { parts, .. } => {
515	            for part in parts {
516	                if let AsstPart::Text(t) = part { out.push_str(t); out.push('\n'); }
517	            }
518	        }
519	        Card::ToolRound { parts } => {
520	            for part in parts {
521	                if let AsstPart::ToolCall { name, input, result, .. } = part {
522	                    out.push_str(&format!("[Tool: {name}]\n"));
523	                    if let Some(obj) = input.as_object() {
524	                        for (k, v) in obj {
525	                            let val = if let Value::String(s) = v { s.clone() } else { v.to_string() };
526	                            out.push_str(&format!("{k}: {val}\n"));
527	                        }
528	                    }
529	                    if let Some((content, _)) = result {
530	                        out.push_str(&format!("[Result]\n{content}\n"));
531	                    }
532	                }
533	            }
534	        }
535	    }
536	    out
537	}
538	
539	fn tool_call_text(part: &AsstPart) -> String {
540	    let mut out = String::new();
541	    if let AsstPart::ToolCall { name, input, result, .. } = part {
