762	// Visible character width, skipping ANSI escape sequences.
763	fn visible_width(s: &str) -> usize {
764	    let mut w = 0usize;
765	    let mut chars = s.chars().peekable();
766	    while let Some(c) = chars.next() {
767	        if c == '\x1b' {
768	            // consume up to and including the final byte of the CSI sequence
769	            for nc in chars.by_ref() {
770	                if nc.is_ascii_alphabetic() { break; }
771	            }
772	        } else {
773	            w += 1;
774	        }
775	    }
776	    w
777	}
