779	// Apply a selection background to a pre-colored ANSI string.
780	// Parses SGR sequences properly so that any explicit background color emitted
781	// by termimad (e.g. `\x1b[48;5;238m` for inline code) is replaced with the
782	// selection background rather than overriding it.
783	fn with_bg(s: &str, bg: &str) -> String {
784	    let bg_seq  = format!("\x1b[{bg}m");
785	    let mut out = bg_seq.clone();
786	    let bytes   = s.as_bytes();
787	    let mut i   = 0;
788	
789	    while i < bytes.len() {
790	        if bytes[i] == b'\x1b' && bytes.get(i + 1) == Some(&b'[') {
791	            // Parse CSI sequence: ESC [ <params> <cmd>
792	            let esc_start   = i;
793	            i += 2;
794	            let params_start = i;
795	            while i < bytes.len() && !bytes[i].is_ascii_alphabetic() { i += 1; }
796	            let cmd    = *bytes.get(i).unwrap_or(&b'm');
797	            let params = &s[params_start..i];
798	            i += 1;
799	
800	            if cmd == b'm' {
801	                out.push_str(&rewrite_sgr(params, &bg_seq));
802	            } else {
803	                out.push_str(&s[esc_start..i]);
804	            }
805	        } else {
806	            let ch_len = s[i..].chars().next().map_or(1, |c| c.len_utf8());
807	            out.push_str(&s[i..i + ch_len]);
808	            i += ch_len;
809	        }
810	    }
811	
812	    out
813	}
814	
815	// Rewrite a single SGR parameter string so that any background colour is
816	// replaced with the selection background. Foreground / attribute codes are
817	// kept; a pure reset gets the background re-appended.
818	fn rewrite_sgr(params: &str, bg_seq: &str) -> String {
819	    if params.is_empty() || params == "0" {
820	        return format!("\x1b[0m{bg_seq}");
821	    }
822	
823	    let mut non_bg: Vec<&str> = Vec::new();
824	    let mut found_bg = false;
825	    let mut segs = params.split(';').peekable();
826	
827	    while let Some(seg) = segs.next() {
828	        match seg {
829	            // Standard background colours 40-47 and bright 100-107
830	            "40"|"41"|"42"|"43"|"44"|"45"|"46"|"47"
831	            |"100"|"101"|"102"|"103"|"104"|"105"|"106"|"107" => {
832	                found_bg = true;
833	            }
834	            // 256-colour or true-colour background: 48;5;N or 48;2;R;G;B
835	            "48" => {
836	                found_bg = true;
837	                match segs.next().as_deref() {
838	                    Some("5") => { segs.next(); }          // skip N
839	                    Some("2") => { segs.next(); segs.next(); segs.next(); } // skip R;G;B
840	                    _ => {}
841	                }
842	            }
843	            // \x1b[49m — reset background to default (termimad uses this, not \x1b[0m)
844	            "49" => { found_bg = true; }
845	            // Reset within a combined sequence — keep it
846	            "0" => non_bg.push("0"),
847	            other => non_bg.push(other),
848	        }
849	    }
850	
851	    if !found_bg {
852	        return format!("\x1b[{params}m");
853	    }
854	
855	    let mut result = String::new();
856	    if !non_bg.is_empty() {
857	        result.push_str(&format!("\x1b[{}m", non_bg.join(";")));
858	    }
859	    result.push_str(bg_seq);
860	    result
861	}
