905	fn git_current_branch(cwd: &str) -> Option<String> {
906	    let out = std::process::Command::new("git")
907	        .args(["rev-parse", "--abbrev-ref", "HEAD"])
908	        .current_dir(cwd)
909	        .output()
910	        .ok()?;
911	    if !out.status.success() { return None; }
912	    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
913	    if s.is_empty() || s == "HEAD" { None } else { Some(s) }
914	}
915	
916	fn create_resume_worktree(cwd: &str, branch: &str) -> Option<String> {
917	    let root_out = std::process::Command::new("git")
918	        .args(["rev-parse", "--show-toplevel"])
919	        .current_dir(cwd)
920	        .output()
921	        .ok()?;
922	    if !root_out.status.success() { return None; }
923	    let repo_root = String::from_utf8_lossy(&root_out.stdout).trim().to_string();
924	
925	    let repo_path = std::path::Path::new(&repo_root);
926	    let parent = repo_path.parent()?;
927	    let repo_name = repo_path.file_name()?.to_str()?;
928	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
929	
930	    // Branch already exists; add a worktree pointing at it.
931	    let _ = std::process::Command::new("git")
932	        .args(["worktree", "add", wt_path.to_str()?, branch])
933	        .current_dir(&repo_root)
934	        .output();
935	
936	    if wt_path.exists() { Some(wt_path.to_string_lossy().to_string()) } else { None }
937	}
938	
939	fn resume_via_entire(dir: &str, branch: &str) {
940	    use std::os::unix::process::CommandExt;
941	
942	    let launch_dir = if !branch.is_empty() {
943	        let current = git_current_branch(dir);
944	        if current.as_deref() != Some(branch) {
945	            create_resume_worktree(dir, branch).unwrap_or_else(|| dir.to_string())
946	        } else {
947	            dir.to_string()
948	        }
949	    } else {
950	        dir.to_string()
951	    };
952	
953	    let mut entire = std::process::Command::new("entire");
954	    entire.arg("resume").current_dir(&launch_dir);
955	    if !branch.is_empty() { entire.arg(branch); }
956	
957	    let Ok(out) = entire.output() else { eprintln!("entire resume failed"); return; };
958	
959	    let cmd_str = String::from_utf8_lossy(&out.stdout).trim().to_string();
960	    if cmd_str.is_empty() { eprintln!("entire resume returned no command"); return; }
961	
962	    let mut parts = cmd_str.split_whitespace();
963	    let Some(prog) = parts.next() else { return; };
964	    let args: Vec<&str> = parts.collect();
965	    let err = std::process::Command::new(prog).args(&args).current_dir(&launch_dir).exec();
966	    eprintln!("exec failed: {err}");
967	}
