fn render_checkpoint_header(cp: &CheckpointData, expanded: bool, term_w: usize) -> String {
    let arrow = if expanded { "▾" } else { "▸" };
    let short_id = if cp.checkpoint_id.len() >= 8 {
        &cp.checkpoint_id[..8]
    } else {
        cp.checkpoint_id.as_str()
    };
    let msg = if cp.commit_message.is_empty() {
        String::new()
    } else {
        format!("  {}", cp.commit_message)
    };
    let ts_part = if !cp.last_turn_ts.is_empty() {
        format!("  \x1b[37m{}\x1b[0m\x1b[42m", rel_time(&cp.last_turn_ts))
    } else {
        String::new()
    };
    let id_part = if short_id.is_empty() {
        String::new()
    } else {
        format!("  \x1b[37m{short_id}\x1b[0m\x1b[42m")
    };

    // Content (visible chars only, no ANSI) for padding calculation.
    let content = format!(
        "  {arrow} \x1b[1;92mcheckpoint\x1b[0m\x1b[42m #{}{id_part}\x1b[97m{msg}\x1b[0m\x1b[42m{ts_part}",
        cp.number,
    );
    let vis = visible_width(&content);
    let pad = term_w.saturating_sub(vis);
    format!("\x1b[42m{content}{}\x1b[0m", " ".repeat(pad))
}

