            match &cards[insert_at] {
                Card::ToolRound { .. } => { insert_at += 1; }
                Card::AsstMsg { ts, .. } if ts.as_str() <= cp.last_turn_ts.as_str() => { insert_at += 1; }
                _ => break,
            }
        }
        cards.insert(insert_at, Card::Checkpoint(cp));
    }
}

