    pub tokens_used: i64,
}

/// Parse a checkpoint's `metadata.json` + `full.jsonl` into a normalized session row.
pub fn dispatch_session(meta_bytes: &[u8], jsonl_bytes: &[u8]) -> Result<ParsedSession> {
