601	fn enrich_hits(hits: &mut Vec<SearchHit>) {
602	    let Ok(conn) = crate::db::connect() else { return };
603	    for hit in hits.iter_mut() {
604	        if let Some(sid) = &hit.session_id {
605	            // Pull agent + remote, plus the first checkpoint's author (matching
606	            // the resolution session_list::query_db uses: name > email > os_user).
607	            if let Ok((agent, updated_at, remote, author_name, author_email, author_os_user)) =
608	                conn.query_row(
609	                    "SELECT s.agent_name, s.updated_at, COALESCE(r.remote, ''),
610	                            COALESCE(c.author_name, ''), COALESCE(c.author_email, ''),
611	                            COALESCE(c.os_user, '')
612	                     FROM sessions s
613	                     LEFT JOIN repositories r
614	                       ON (s.cwd = r.directory OR s.cwd LIKE r.directory || '/%')
615	                     LEFT JOIN checkpoints c
616	                       ON c.session_id = s.session_id
617	                      AND c.checkpoint_number = (
618	                            SELECT MIN(checkpoint_number) FROM checkpoints
619	                            WHERE session_id = s.session_id
620	                          )
621	                     WHERE s.session_id = ?1",
622	                    [sid.as_str()],
623	                    |row| Ok((
624	                        row.get::<_, String>(0)?,
625	                        row.get::<_, String>(1)?,
626	                        row.get::<_, String>(2)?,
627	                        row.get::<_, String>(3)?,
628	                        row.get::<_, String>(4)?,
629	                        row.get::<_, String>(5)?,
630	                    )),
631	                )
632	            {
633	                hit.agent      = agent;
634	                hit.updated_at = updated_at;
635	                hit.backed_up  = true;
636	                hit.remote     = remote;
637	                hit.author     = if !author_name.trim().is_empty() { author_name }
638	                                 else if !author_email.trim().is_empty() { author_email }
639	                                 else { author_os_user };
640	            }
641	        } else if let Some(dir) = &hit.repo_dir.clone() {
642	            if let Ok(remote) = conn.query_row(
643	                "SELECT COALESCE(remote, '') FROM repositories WHERE directory = ?1",
644	                [dir.as_str()],
645	                |row| row.get::<_, String>(0),
646	            ) {
647	                hit.remote = remote;
648	            }
649	        }
650	    }
651	}
