/// Open a session and jump to the turn identified by `turn_id` (the JSONL
/// message `uuid`). Falls back to timestamp matching if uuid lookup fails,
/// and to the last item if neither matches.
pub fn run_at(session_id: &str, turn_id: Option<&str>) -> Result<bool> {
    let path = find_session(session_id)
        .with_context(|| format!("no session file found for '{session_id}'"))?;

    let raw = std::fs::read_to_string(&path)
        .with_context(|| format!("cannot read {}", path.display()))?;

    // Resolve turn_id (JSONL message uuid) → timestamp so pager can match it.
    let resolved_ts: Option<String> = turn_id.and_then(|tid| {
        for line in raw.lines() {
            let Ok(v) = serde_json::from_str::<serde_json::Value>(line) else { continue };
