1	//! Shared session-list loading for both `gossamer sessions` (top-level) and
2	//! `gossamer repo` (drilled in). Both views need the same data: DB rows from
3	//! `sessions`, augmented with fresher info from any local Claude Code JSONLs
4	//! in `~/.claude/projects`. The only thing that differs is scope.
5	
6	use chrono::{DateTime, Utc};
7	use std::io::BufRead;
8	use std::path::{Path, PathBuf};
9	
10	use crate::db;
11	use crate::entity::repository::Repository;
12	
13	pub struct DisplaySession {
14	    pub session_id: String,
15	    pub session_name: String,
16	    pub cwd: String,
17	    pub branch: String,
18	    pub updated_at: DateTime<Utc>,
19	    pub agent_name: String,
20	    pub backed_up: bool,
21	    /// Display name of whoever initiated the session — taken from the author
22	    /// of the first checkpoint (lowest checkpoint_number). Empty for sessions
23	    /// that have never been checkpointed (live JSONL only) or whose author
24	    /// couldn't be resolved.
25	    pub author: String,
26	    /// True when session_name came from an explicit `/rename` (custom-title
27	    /// entry in the JSONL); false when it's the derived first-prompt fallback.
28	    /// Drives the italic/plain distinction in the list renderers.
29	    pub name_is_explicit: bool,
30	    /// Sum of output tokens generated across all assistant turns. 0 when the
31	    /// session has never been indexed or has no local JSONL.
32	    pub tokens_used: i64,
33	}
34	
35	/// SGR color for a token count — a graduated sequence using standard 16-color
36	/// ANSI so the terminal's own palette controls the actual RGB values.
37	///
38	/// Dark theme: dim → progressively brighter (more tokens = more visible).
39	/// Light theme: muted → progressively darker/more saturated.
40	pub fn token_color(tokens: i64) -> &'static str {
41	    if crate::theme::get().is_dark {
42	        match tokens {
43	            t if t < 5_000   => "90",   // dim gray   — trace usage
44	            t if t < 20_000  => "37",   // white      — light
45	            t if t < 100_000 => "33",   // yellow     — moderate
46	            t if t < 500_000 => "93",   // bright yellow — heavy
47	            _                => "1;31", // bold red   — very heavy
48	        }
49	    } else {
50	        match tokens {
51	            t if t < 5_000   => "90",   // light gray — trace usage
52	            t if t < 20_000  => "36",   // cyan       — light
53	            t if t < 100_000 => "34",   // blue       — moderate
54	            t if t < 500_000 => "35",   // magenta    — heavy
55	            _                => "1;31", // bold red   — very heavy
56	        }
57	    }
58	}
59	
60	/// Format a token count compactly for display (empty string for zero).
61	pub fn fmt_tokens(n: i64) -> String {
62	    if n <= 0 { return String::new(); }
63	    if n < 1_000 { return format!("{n}"); }
64	    if n < 10_000 { return format!("{:.1}k", n as f64 / 1_000.0); }
65	    if n < 1_000_000 { return format!("{}k", n / 1_000); }
66	    format!("{:.1}M", n as f64 / 1_000_000.0)
67	}
68	
69	/// Collapse interior whitespace (newlines, tabs, runs of spaces) into a single
70	/// space. session_name flows into fixed-width raw-mode columns; an interior
71	/// '\n' jumps the cursor and clobbers the row layout — see git history for
72	/// the bee0c590 incident. Cheap to do everywhere session_name is produced.
73	pub fn sanitize_one_line(text: &str) -> String {
74	    let mut out = String::with_capacity(text.len());
75	    let mut prev_space = false;
76	    for c in text.chars() {
77	        if c.is_whitespace() {
78	            if !prev_space && !out.is_empty() {
79	                out.push(' ');
80	                prev_space = true;
81	            }
82	        } else {
83	            out.push(c);
84	            prev_space = false;
85	        }
86	    }
87	    while out.ends_with(' ') { out.pop(); }
88	    out
89	}
90	
91	pub enum Scope<'a> {
92	    /// All tracked sessions across every repo.
93	    All,
94	    /// Sessions belonging to a single repo. Matched primarily by `repo_id`;
95	    /// older rows without `repo_id` are caught by `cwd LIKE <directory>%`.
96	    Repo(&'a Repository),
97	}
98	
99	/// Load sessions, optionally scoped to one repo. With `include_old = false`,
100	/// only sessions updated within the last 3 days are returned. Result is sorted
101	/// most-recent-first; callers are free to re-sort.
102	pub fn fetch(scope: Scope, include_old: bool) -> Vec<DisplaySession> {
103	    let cutoff = Utc::now() - chrono::Duration::days(3);
104	    let mut sessions = query_db(&scope);
105	    // Augment first, then cutoff-filter on the final updated_at. Otherwise a
106	    // DB row with a stale updated_at but an actively-touched local JSONL gets
107	    // dropped here, then re-added as unbacked when augment can't find it —
108	    // diverging from the repo view where include_old=true skips this filter.
109	    augment_with_jsonls(&mut sessions, &scope, include_old, cutoff);
110	    if !include_old {
111	        sessions.retain(|s| s.updated_at >= cutoff);
112	    }
113	    sessions.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
114	    sessions
115	}
116	
117	fn query_db(scope: &Scope) -> Vec<DisplaySession> {
118	    let Ok(conn) = db::connect() else { return Vec::new(); };
119	    let mut out: Vec<DisplaySession> = Vec::new();
120	    let map = |row: &rusqlite::Row<'_>| -> rusqlite::Result<DisplaySession> {
121	        let ts: String = row.get(4)?;
122	        let author_name: String = row.get(6)?;
123	        let author_email: String = row.get(7)?;
124	        let os_user: String = row.get(8)?;
125	        let raw_name: String = row.get(1)?;
126	        let name_is_explicit: i64 = row.get(9)?;
127	        let tokens_used: i64 = row.get(10)?;
128	        Ok(DisplaySession {
129	            session_id: row.get(0)?,
130	            session_name: sanitize_one_line(&raw_name),
131	            cwd: row.get(2)?,
132	            branch: row.get(3)?,
133	            updated_at: DateTime::parse_from_rfc3339(&ts)
134	                .map(|dt| dt.with_timezone(&Utc))
135	                .unwrap_or_else(|_| Utc::now()),
136	            agent_name: row.get(5)?,
137	            backed_up: true,
138	            author: resolve_author_label(&author_name, &author_email, &os_user),
139	            name_is_explicit: name_is_explicit != 0,
140	            tokens_used,
141	        })
142	    };
143	    // Pull the author of the FIRST checkpoint (lowest checkpoint_number) for
144	    // each session — that's whoever initiated the first message. Sessions
145	    // without checkpoints (shadow-only) get NULLs which COALESCE turns into
146	    // empty strings, leaving `author` blank.
147	    let cols = "
148	        s.session_id, s.session_name, s.cwd, COALESCE(s.branch,''),
149	        s.updated_at, s.agent_name,
150	        COALESCE(c.author_name, ''), COALESCE(c.author_email, ''), COALESCE(c.os_user, ''),
151	        s.name_is_explicit, COALESCE(s.tokens_used, 0)
152	    ";
153	    let join = "
154	        LEFT JOIN checkpoints c
155	          ON c.session_id = s.session_id
156	         AND c.last_turn_ts = (
157	               SELECT MIN(last_turn_ts) FROM checkpoints WHERE session_id = s.session_id
158	             )
159	    ";
160	    match scope {
161	        Scope::All => {
162	            let Ok(mut stmt) = conn.prepare(
163	                &format!("SELECT {cols} FROM sessions s {join} ORDER BY s.updated_at DESC")
164	            ) else { return out; };
165	            if let Ok(rows) = stmt.query_map([], map) {
166	                for r in rows.flatten() { out.push(r); }
167	            }
168	        }
169	        Scope::Repo(r) => {
170	            let Ok(mut stmt) = conn.prepare(&format!(
171	                "SELECT {cols} FROM sessions s {join}
172	                 WHERE s.repo_id = ?1 OR (s.repo_id IS NULL AND s.cwd LIKE ?2)
173	                 ORDER BY s.updated_at DESC"
174	            )) else { return out; };
175	            let pattern = format!("{}%", r.directory);
176	            if let Ok(rows) = stmt.query_map(rusqlite::params![r.id as i64, pattern], map) {
177	                for row in rows.flatten() { out.push(row); }
178	            }
179	        }
180	    }
181	    out
182	}
183	
184	fn cwd_os_user(cwd: &str) -> Option<String> {
185	    let rest = cwd.strip_prefix("/Users/").or_else(|| cwd.strip_prefix("/home/"))?;
186	    let user = rest.split('/').next()?;
187	    if user.is_empty() { None } else { Some(user.to_string()) }
188	}
189	
190	fn resolve_author_label(name: &str, email: &str, os_user: &str) -> String {
191	    if !name.trim().is_empty() { return name.to_string(); }
192	    if !email.trim().is_empty() { return email.to_string(); }
193	    if !os_user.trim().is_empty() { return os_user.to_string(); }
194	    String::new()
195	}
196	
197	fn augment_with_jsonls(
198	    sessions: &mut Vec<DisplaySession>,
199	    scope: &Scope,
200	    include_old: bool,
201	    cutoff: DateTime<Utc>,
202	) {
203	    let Ok(home) = std::env::var("HOME") else { return; };
204	    let projects = PathBuf::from(&home).join(".claude/projects");
205	    let Ok(dirs) = std::fs::read_dir(&projects) else { return; };
206	
207	    for dir_entry in dirs.flatten() {
208	        let dir = dir_entry.path();
209	        if !dir.is_dir() { continue }
210	        let Ok(files) = std::fs::read_dir(&dir) else { continue };
211	        for f in files.flatten() {
212	            let path = f.path();
213	            if path.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue }
214	            let Some(session_id) = path.file_stem().and_then(|s| s.to_str()).map(str::to_string)
215	                else { continue };
216	
217	            let file_mtime = f.metadata().ok()
218	                .and_then(|m| m.modified().ok())
219	                .map(DateTime::<Utc>::from)
220	                .unwrap_or_else(Utc::now);
221	            if !include_old && file_mtime < cutoff { continue }
222	
223	            let parsed = parse_jsonl(&path);
224	
225	            if let Some(existing) = sessions.iter_mut().find(|s| s.session_id == session_id) {
226	                if !parsed.session_name.is_empty() { existing.session_name = parsed.session_name; }
227	                if file_mtime > existing.updated_at { existing.updated_at = file_mtime; }
228	                if !parsed.branch.is_empty() { existing.branch = parsed.branch; }
229	                // A custom-title in the JSONL outranks the DB flag. Without
230	                // this, /rename'd sessions stay tagged as "derived" until the
231	                // next index run, so they render gray in the lists.
232	                if parsed.name_is_explicit { existing.name_is_explicit = true; }
233	                // JSONL token count is authoritative when present (live data).
234	                if parsed.tokens_used > 0 { existing.tokens_used = parsed.tokens_used; }
235	                // Sessions inserted by the SessionStart hook but never indexed
236	                // from a checkpoint branch have no `checkpoints` row, so the
237	                // author column came back empty. Fall back to the cwd's
238	                // os-user — same fallback used for brand-new untracked rows.
239	                if existing.author.is_empty() {
240	                    let cwd = if !existing.cwd.is_empty() { existing.cwd.as_str() } else { parsed.cwd.as_str() };
241	                    existing.author = cwd_os_user(cwd).unwrap_or_default();
242	                }
243	                continue;
244	            }
245	
246	            // Untracked session (only in local JSONL). When scoped to one
247	            // repo, only include if its cwd actually belongs to that repo.
248	            if let Scope::Repo(r) = scope {
249	                if !parsed.cwd.starts_with(r.directory.as_str()) { continue }
250	            }
251	
252	            let author = cwd_os_user(&parsed.cwd).unwrap_or_default();
253	            sessions.push(DisplaySession {
254	                session_id,
255	                session_name: parsed.session_name,
256	                cwd: parsed.cwd,
257	                branch: parsed.branch,
258	                updated_at: file_mtime,
259	                agent_name: "Claude Code".to_string(),
260	                backed_up: false,
261	                author,
262	                name_is_explicit: parsed.name_is_explicit,
263	                tokens_used: parsed.tokens_used,
264	            });
265	        }
266	    }
267	}
268	
269	struct ParsedJsonl {
270	    session_name: String,
271	    cwd: String,
272	    branch: String,
273	    name_is_explicit: bool,
274	    tokens_used: i64,
275	}
276	
277	fn parse_jsonl(path: &Path) -> ParsedJsonl {
278	    let mut out = ParsedJsonl {
279	        session_name: String::new(),
280	        cwd: String::new(),
281	        branch: String::new(),
282	        name_is_explicit: false,
283	        tokens_used: 0,
284	    };
285	    let Ok(file) = std::fs::File::open(path) else { return out; };
286	    let reader = std::io::BufReader::new(file);
287	    let mut last_prompt = String::new();
288	    let mut custom_title = String::new();
289	
290	    for line in reader.lines().flatten() {
291	        let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
292	        match v["type"].as_str() {
293	            Some("custom-title") => {
294	                if let Some(t) = v["customTitle"].as_str() {
295	                    if !t.trim().is_empty() { custom_title = t.to_string(); }
296	                }
297	            }
298	            Some("user") | Some("system") => {
299	                if out.cwd.is_empty() {
300	                    if let Some(c) = v["cwd"].as_str() { out.cwd = c.to_string(); }
301	                }
302	            }
303	            Some("assistant") => {
304	                if let Some(n) = v["message"]["usage"]["output_tokens"].as_i64() {
305	                    out.tokens_used += n;
306	                }
307	            }
308	            _ => {}
309	        }
310	        if v["type"].as_str() == Some("user") {
311	            if let Some(t) = user_text(&v["message"]["content"]) {
312	                last_prompt = t;
313	            }
314	        }
315	        if let Some(b) = v["gitBranch"].as_str() {
316	            if !b.is_empty() { out.branch = b.to_string(); }
317	        }
318	    }
319	    if !custom_title.is_empty() {
320	        out.session_name = custom_title;
321	        out.name_is_explicit = true;
322	    } else {
